    end;
  end if;

  if upper('&hkd_file') in ('ALL', 'QUOTE_ALPENWERK_Q5531.PDF') then
    declare
      l_b64 clob;
    begin
      sys.dbms_lob.createtemporary(l_b64, true);
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      put('quote_alpenwerk_q5531.pdf', l_b64);
    end;
  end if;

  if upper('&hkd_file') in ('ALL', 'DATASHEET_PUMP_X200.PDF') then
    declare
      l_b64 clob;
    begin
      sys.dbms_lob.createtemporary(l_b64, true);
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      put('datasheet_pump_x200.pdf', l_b64);
    end;
  end if;

  if upper('&hkd_file') in ('ALL', 'LETTER_EMPLOYMENT_CHANGE.PDF') then
    declare
      l_b64 clob;
    begin
      sys.dbms_lob.createtemporary(l_b64, true);
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      put('letter_employment_change.pdf', l_b64);
    end;
  end if;

  if upper('&hkd_file') in ('ALL', 'SCAN_FAX_AMENDMENT.PDF') then
    declare
      l_b64 clob;
    begin
      sys.dbms_lob.createtemporary(l_b64, true);
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      put('scan_fax_amendment.pdf', l_b64);
    end;
  end if;

  if upper('&hkd_file') in ('ALL', 'PROFORMA_ALPENWERK_PF5531.PDF') then
    declare
      l_b64 clob;
    begin
      sys.dbms_lob.createtemporary(l_b64, true);
      sys.dbms_lob.append(l_b64, '');
      sys.dbms_lob.append(l_b64, '');
      put('proforma_alpenwerk_pf5531.pdf', l_b64);
    end;
  end if;

  if upper('&hkd_file') in ('ALL', 'REMINDER_FERROTEK_1042.PDF') then
    declare
