      sys.dbms_lob.append(l_b64, '');
      put('reminder_ferrotek_1042.pdf', l_b64);
    end;
  end if;

  if upper('&hkd_file') in ('ALL', 'DELIVERY_NOTE_NORDLICHT_LS2207.PDF') then
    declare
