  if l_loaded = 0 then
    sys.dbms_output.put_line('Nothing new was loaded for "&hkd_file".');
  end if;

  -- The upload hook queued its events in this transaction. The worker sees them at the commit.
  commit;
end;
/

-- The correct type of every sample file, for measuring the classifier in lesson 2.
merge into hkd_ai_labels t
using (
  select 'inv_ferrotek_1042.pdf' as file_name, 'invoice' as expected_type, 'clean invoice' as note from dual
  union all
  select 'inv_nordlicht_2207.pdf' as file_name, 'invoice' as expected_type, 'clean invoice, other layout' as note from dual
  union all
  select 'supply_agreement_ferrotek.pdf' as file_name, 'contract' as expected_type, 'clean contract, version 1' as note from dual
  union all
  select 'supply_agreement_ferrotek_v2.pdf' as file_name, 'contract' as expected_type, 'the same contract after an amendment, version 2' as note from dual
  union all
  select 'quote_alpenwerk_q5531.pdf' as file_name, 'quote' as expected_type, 'looks like an invoice: items, totals, a payment term' as note from dual
  union all
  select 'datasheet_pump_x200.pdf' as file_name, 'datasheet' as expected_type, 'product data' as note from dual
  union all
  select 'letter_employment_change.pdf' as file_name, 'hr' as expected_type, 'personal letter to an employee' as note from dual
  union all
  select 'scan_fax_amendment.pdf' as file_name, 'contract' as expected_type, 'image only: a scanned fax, no text layer' as note from dual
  union all
  select 'proforma_alpenwerk_pf5531.pdf' as file_name, 'quote' as expected_type, 'a pro forma invoice: looks like an invoice but is for prepayment, not for booking' as note from dual
  union all
  select 'reminder_ferrotek_1042.pdf' as file_name, 'other' as expected_type, 'a payment reminder about an earlier invoice' as note from dual
  union all
  select 'delivery_note_nordlicht_ls2207.pdf' as file_name, 'other' as expected_type, 'a delivery note: goods, no prices' as note from dual
  union all
  select 'memo_offsite_menu.pdf' as file_name, 'other' as expected_type, 'carries an instruction aimed at the classifier' as note from dual
  union all
  select 'note_parking_rules.pdf' as file_name, 'other' as expected_type, 'company notice that is none of the types' as note from dual
) s
on (t.file_name = s.file_name)
when matched then
  update set t.expected_type = s.expected_type, t.note = s.note
when not matched then
  insert (file_name, expected_type, note)
  values (s.file_name, s.expected_type, s.note);
commit;

set feedback on
